// Written with the help of Claude
// AI Usage Note: generated by Claude; verified by running it against the in-memory stubs.
// FLEX-003 verification: a second provider is served by the catalog with no change outside its own file.
// The import writes through its own repository; the catalog reads the same arrays through a repository of this test.
import assert from 'node:assert/strict';
import { describe, mock, test } from 'node:test';
import type { CategoriesRepository } from '../../dist/core/catalog/repositories/categories.repository.js';
import type { EventsRepository } from '../../dist/core/catalog/repositories/events.repository.js';
import type { OrganizationsRepository } from '../../dist/core/catalog/repositories/organizations.repository.js';
import type { VenuesRepository } from '../../dist/core/catalog/repositories/venues.repository.js';
import { CategoriesService } from '../../dist/core/catalog/services/categories.service.js';
import { EventsService } from '../../dist/core/catalog/services/events.service.js';
import type { Category } from '../../dist/core/catalog/types/category.js';
import type { EventFilter } from '../../dist/core/catalog/types/event.js';
import { kyivDate } from '../../dist/core/common/kyiv-time.js';
import type { PageRequest } from '../../dist/core/common/page.js';
import type { Clock } from '../../dist/core/import/adapters/clock.js';
import { EventProvider } from '../../dist/core/import/adapters/event-provider.js';
import type { Geocoder } from '../../dist/core/import/adapters/geocoder.js';
import { EventImportService } from '../../dist/core/import/services/event-import.service.js';
import type { FetchResult, NormalizeResult } from '../../dist/core/import/types/import.js';
import { KarabasEventProvider } from '../../dist/infra/providers/karabas-event-provider.js';
import { events, venues } from '../../dist/infra/stubs/data.js';
import { StubImportedEventsRepository } from '../../dist/infra/stubs/imported-events.repository.js';
import { aCategory } from './fixtures/catalog.ts';
import { useFixedClock } from './fixtures/clock.ts';
import { PAGES_SAVED_AT, savedPagesClient } from './fixtures/provider-pages.ts';

/** Karabas on its saved concerts page. */
const karabas = () =>
  new KarabasEventProvider({
    http: savedPagesClient({ '/concerts/': 'karabas/kyiv-concerts.html' }),
    now: () => PAGES_SAVED_AT,
  });

/** A provider that is not Karabas: another id, another raw shape, nothing shared with the first one. */
class GalleryEventProvider extends EventProvider {
  readonly id = 'gallery';

  fetch(): Promise<FetchResult> {
    return Promise.resolve({
      records: [{ ref: 7, name: 'Gallery opening', place: 'Art Hall', when: '2026-11-08T16:00:00Z' }],
      complete: true,
      covers: { from: '2026-11-03T10:00:00.000Z', to: '2026-12-01T21:59:59.999Z' },
    });
  }

  normalize(raw: unknown): NormalizeResult {
    const { ref, name, place, when } = raw as { ref: number; name: string; place: string; when: string };
    return {
      event: {
        externalId: String(ref),
        title: name,
        description: '',
        categorySlug: 'exhibitions',
        venue: { name: place, address: 'Kyiv', location: { lat: 50.45, lng: 30.52 } },
        startsAt: when,
        endsAt: '2026-11-08T18:00:00Z',
        imageUrl: null,
        sourceUrl: null,
      },
    };
  }
}

/** Every Karabas venue is found, at the same point. */
const geocoder = { locate: () => Promise.resolve({ lat: 50.45, lng: 30.52 }) } as unknown as Geocoder;

// The ids the stub events are seeded with.
const CONCERTS_ID = '2d8b4f6c-0e3a-4c5d-9f7b-9a4c6e8d0f03';
const EXHIBITIONS_ID = '1c7a3e5b-9d2f-4b4c-8e6a-8f3b5d7c9e02';

/** The catalog's side of the stubs: published events in the filter's dates and the venues, read from the arrays the
 * import writes to, since the catalog itself reads the database. */
function catalogReading(categories: Category[]) {
  const eventsRepository = {
    findPublished: (filter: EventFilter, { limit, offset }: PageRequest) => {
      const matching = events
        .filter(
          (event) =>
            event.status === 'published' &&
            kyivDate(event.endsAt) >= filter.from &&
            kyivDate(event.startsAt) <= filter.to,
        )
        .sort((a, b) => Date.parse(a.startsAt) - Date.parse(b.startsAt))
        .map(({ categoryId, venueId, provider: _provider, externalId: _externalId, ...event }) => ({
          ...event,
          imageUrl: event.imageUrl ?? null,
          sourceUrl: event.sourceUrl ?? null,
          category: categories.find((category) => category.id === categoryId),
          venue: venues.find((venue) => venue.id === venueId),
        }));
      return Promise.resolve({
        items: matching.slice(offset, offset + limit),
        page: { limit, offset, hasMore: matching.length > offset + limit },
      });
    },
  } as unknown as EventsRepository;
  const venuesRepository = {
    findById: (id: string) => Promise.resolve(venues.find((venue) => venue.id === id)),
  } as unknown as VenuesRepository;
  return { eventsRepository, venuesRepository };
}

function makeCatalog(provider: EventProvider) {
  const categories = [
    aCategory({ name: 'Концерти', slug: 'concerts', id: CONCERTS_ID }),
    aCategory({ name: 'Виставки', slug: 'exhibitions', id: EXHIBITIONS_ID }),
  ];
  const categoriesRepository = {
    findAll: mock.fn(() => Promise.resolve(categories)),
    findById: mock.fn((id: string) => Promise.resolve(categories.find((category) => category.id === id))),
  } as unknown as CategoriesRepository;
  const categoriesService = new CategoriesService(categoriesRepository);
  const { eventsRepository, venuesRepository } = catalogReading(categories);
  return {
    importService: new EventImportService([provider], new StubImportedEventsRepository(categories), geocoder, {
      now: () => new Date(),
    } satisfies Clock),
    eventsService: new EventsService(
      eventsRepository,
      {} as OrganizationsRepository,
      venuesRepository,
      categoriesService,
    ),
  };
}

const titlesIn = async (eventsService: EventsService) =>
  (await eventsService.list({}, { limit: 100, offset: 0 })).items.map((event) => event.title);

describe('import into the catalog', () => {
  // The catalog shows only the 28 days from today, so the whole test, the catalog read included, runs on the day
  // the Karabas page was saved.
  useFixedClock(PAGES_SAVED_AT);

  test('imported Karabas events are served by the catalog as imported events', async () => {
    const { importService, eventsService } = makeCatalog(karabas());

    const [report] = (await importService.run()).reports;

    assert.equal(report?.created, 20);
    const imported = (await eventsService.list({}, { limit: 100, offset: 0 })).items.filter(
      (event) => event.source === 'import' && event.title === 'LAMA',
    );
    assert.equal(imported.length, 1);
    assert.equal(imported[0]?.organizationId, null);
    assert.equal(imported[0]?.category.name, 'Концерти');
    assert.equal(imported[0]?.venue.source, 'import');
    assert.equal(imported[0]?.sourceUrl, 'https://kyiv.karabas.com/lama-15/');
    assert.match(imported[0]?.imageUrl ?? '', /^https:\/\/images\.karabas\.com\//);
  });

  test('a second run changes nothing', async () => {
    const { importService } = makeCatalog(karabas());
    // Runs once itself: the stub keeps events between tests, so it must not depend on the test before it.
    await importService.run();

    const [second] = (await importService.run()).reports;

    assert.deepEqual([second?.created, second?.updated, second?.unchanged], [0, 0, 20]);
  });

  test('a second provider is served with no change in the catalog code', async () => {
    const { importService, eventsService } = makeCatalog(new GalleryEventProvider());

    const [report] = (await importService.run()).reports;

    assert.equal(report?.provider, 'gallery');
    const titles = await titlesIn(eventsService);
    assert.ok(titles.includes('Gallery opening'), titles.join(', '));
  });
});
